package com.forecast.exception;  import lombok.extern.slf4j.Slf4j; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.ExceptionHandler; import org.springframework.web.bind.annotation.RestControllerAdvice;  import java.time.LocalDateTime; import java.util.LinkedHashMap; import java.util.Map;  @RestControllerAdvice @Slf4j public class GlobalExceptionHandler {      @ExceptionHandler(ForecastNotFoundException.class)     public ResponseEntity<Map<String, Object>> handleForecastNotFound(ForecastNotFoundException ex) {         log.error("Forecast not found: {}", ex.getMessage());         Map<String, Object> body = createErrorResponse(HttpStatus.NOT_FOUND, ex.getMessage());         return new ResponseEntity<>(body, HttpStatus.NOT_FOUND);     }      @ExceptionHandler(OptimisticLockException.class)     public ResponseEntity<Map<String, Object>> handleOptimisticLock(OptimisticLockException ex) {         log.error("Optimistic lock error: {}", ex.getMessage());         Map<String, Object> body = createErrorResponse(HttpStatus.CONFLICT, ex.getMessage());         return new ResponseEntity<>(body, HttpStatus.CONFLICT);     }      @ExceptionHandler(RuntimeException.class)     public ResponseEntity<Map<String, Object>> handleRuntimeException(RuntimeException ex) {         log.error("Runtime exception: {}", ex.getMessage(), ex);         Map<String, Object> body = createErrorResponse(HttpStatus.BAD_REQUEST, ex.getMessage());         return new ResponseEntity<>(body, HttpStatus.BAD_REQUEST);     }      @ExceptionHandler(Exception.class)     public ResponseEntity<Map<String, Object>> handleException(Exception ex) {         log.error("Unexpected error: {}", ex.getMessage(), ex);         Map<String, Object> body = createErrorResponse(HttpStatus.INTERNAL_SERVER_ERROR, "An unexpected error occurred");         return new ResponseEntity<>(body, HttpStatus.INTERNAL_SERVER_ERROR);     }      private Map<String, Object> createErrorResponse(HttpStatus status, String message) {         Map<String, Object> body = new LinkedHashMap<>();         body.put("timestamp", LocalDateTime.now());         body.put("status", status.value());         body.put("error", message);         return body;     } }